<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WastedToken Mint — Physical Proof of Chaos</title>
<style>
:root{
  --ink:#0b0d10;--paper:#e9e5dc;--muted:#a9a69d;--line:#30343a;
  --orange:#ff5b2d;--cream:#f3efe6;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;background:var(--ink);color:var(--cream);
  font-family:Arial,Helvetica,sans-serif;letter-spacing:.02em;
}
header{
  position:fixed;z-index:5;top:0;left:0;right:0;display:flex;
  align-items:center;justify-content:space-between;padding:24px 5vw;
  background:linear-gradient(#0b0d10ee,transparent);pointer-events:none
}
header>*{pointer-events:auto}
.logo{font-weight:900;letter-spacing:.14em;font-size:13px;text-transform:uppercase}
.logo span{color:var(--orange)}
nav{display:flex;gap:28px;font-size:11px;text-transform:uppercase;letter-spacing:.16em}
nav a{color:var(--cream);text-decoration:none;opacity:.72}
nav a:hover{opacity:1;color:var(--orange)}
.hero{
  min-height:100vh;display:grid;grid-template-columns:1fr 1fr;
  align-items:center;padding:100px 5vw 60px;gap:3vw;overflow:hidden;
  background:
    radial-gradient(circle at 75% 43%,#252a2f 0,#111519 28%,transparent 55%),
    linear-gradient(115deg,#0b0d10,#12161a 60%,#090a0c);
}
.hero-copy{max-width:590px}
.eyebrow{font-size:11px;letter-spacing:.28em;text-transform:uppercase;color:var(--orange);font-weight:bold;margin-bottom:24px}
h1{font-size:clamp(54px,8vw,118px);line-height:.84;letter-spacing:-.08em;margin:0 0 30px;text-transform:uppercase}
h1 em{font-style:normal;color:var(--orange)}
.lede{color:#bdbab1;max-width:420px;line-height:1.7;font-size:16px}
.hero-actions{display:flex;align-items:center;gap:24px;margin-top:34px}
.cta,.buy{
  border:0;background:var(--orange);color:#170d09;padding:15px 22px;
  font-weight:900;text-transform:uppercase;letter-spacing:.14em;font-size:11px;
  cursor:pointer;transition:.2s transform,.2s background
}
.cta:hover,.buy:hover{transform:translateY(-3px);background:#ff784e}
.micro{font-size:10px;letter-spacing:.14em;color:#777a7b;text-transform:uppercase}
#coin-hero{
  width:100%;height:auto;aspect-ratio:1/1;display:block;
  filter:drop-shadow(0 25px 38px #000b)
}
.section{padding:120px 5vw}
.about{display:grid;grid-template-columns:.8fr 1.2fr;gap:9vw;border-top:1px solid var(--line)}
.section-kicker{color:var(--orange);font-size:11px;letter-spacing:.24em;text-transform:uppercase;font-weight:bold}
h2{font-size:clamp(38px,5vw,76px);line-height:.9;letter-spacing:-.065em;text-transform:uppercase;margin:18px 0}
.about p{color:#aaa9a3;max-width:650px;font-size:19px;line-height:1.7;margin:0}
.stats{display:flex;gap:55px;margin-top:45px}
.stat strong{display:block;font-size:32px;color:var(--cream)}
.stat small{color:#777a7b;text-transform:uppercase;font-size:10px;letter-spacing:.14em}
.collection{background:var(--paper);color:var(--ink);padding-top:100px}
.collection-intro{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-bottom:46px}
.collection h2{margin-bottom:0}
.collection-intro p{max-width:320px;color:#6d6b65;font-size:14px;line-height:1.6}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.edition{position:relative;background:#d7d3c9;min-height:430px;padding:16px;display:flex;flex-direction:column;overflow:hidden}
.edition-canvas{width:100%;aspect-ratio:1/1;display:block}
.edition-info{margin-top:auto;border-top:1px solid #aaa69d;padding-top:15px}
.edition-name{font-weight:900;text-transform:uppercase;font-size:20px;letter-spacing:.02em}
.edition-meta{display:flex;justify-content:space-between;align-items:center;margin-top:8px;color:#716f68;font-size:10px;text-transform:uppercase;letter-spacing:.12em}
.edition .buy{margin-top:17px;width:100%;background:var(--ink);color:var(--cream)}
.edition .buy:hover{background:var(--orange);color:#180d09}
.badge{font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}
.sold .badge{color:#b23a23}.coming .badge{color:#746a51}
.sold,.coming{background:#c8c4b9}.sold .edition-canvas,.coming .edition-canvas{opacity:.73}
footer{padding:40px 5vw;border-top:1px solid var(--line);display:flex;justify-content:space-between;color:#74777a;text-transform:uppercase;font-size:10px;letter-spacing:.14em}
@media(max-width:800px){
  nav{display:none}.hero{grid-template-columns:1fr;padding-top:110px}.hero-copy{order:1}.hero canvas{order:0;max-width:620px;margin:auto}
  .about{grid-template-columns:1fr;gap:25px}.grid{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:480px){.section{padding:80px 6vw}.grid{grid-template-columns:1fr}.edition{min-height:390px}footer{display:block;line-height:2.2}}
</style>
</head>
<body>
<header>
  <div class="logo">Wasted<span>Token</span> / Mint</div>
  <nav><a href="#about">The mint</a><a href="#collection">Collection</a><a href="#contact">Contact</a></nav>
</header>

<main>
<section class="hero">
  <div class="hero-copy">
    <div class="eyebrow">Object 001 / minted for the committed</div>
    <h1>Proof<br>of <em>chaos.</em></h1>
    <p class="lede">WastedToken Mint makes physical challenge coins for impossible dares, legendary nights, and the stories that get better every time they are told.</p>
    <div class="hero-actions">
      <a class="cta" href="#collection">Explore the drop</a>
      <span class="micro">Hand-finished · numbered · tangible</span>
    </div>
  </div>
  <canvas id="coin-hero" aria-label="Animated WastedToken challenge coin"></canvas>
</section>

<section class="section about" id="about">
  <div>
    <div class="section-kicker">A serious mint for unserious legends</div>
    <h2>Make it<br>count.</h2>
  </div>
  <div>
    <p>Every WastedToken is struck like a medal and earned like a scar. We design dense, tactile challenge coins with raised relief, reeded edges, and just enough precious metal to make bad decisions feel ceremonial.</p>
    <div class="stats">
      <div class="stat"><strong>01</strong><small>coin per story</small></div>
      <div class="stat"><strong>∞</strong><small>ways to earn it</small></div>
      <div class="stat"><strong>0%</strong><small>digital nonsense</small></div>
    </div>
  </div>
</section>

<section class="section collection" id="collection">
  <div class="collection-intro">
    <div><div class="section-kicker">The inaugural series</div><h2>Choose<br>your metal.</h2></div>
    <p>Four finishes. One code: carry the proof, keep the story.</p>
  </div>
  <div class="grid">
    <div class="edition" data-edition="bronze" data-state="available">
      <canvas class="edition-canvas"></canvas>
      <div class="edition-info"><div class="edition-name">Bronze</div><div class="edition-meta"><span>Warm strike / 001–250</span><span class="badge">Available</span></div><button class="buy">Add to cart</button></div>
    </div>
    <div class="edition" data-edition="silver" data-state="available">
      <canvas class="edition-canvas"></canvas>
      <div class="edition-info"><div class="edition-name">Silver</div><div class="edition-meta"><span>Cold strike / 001–100</span><span class="badge">Available</span></div><button class="buy">Add to cart</button></div>
    </div>
    <div class="edition sold" data-edition="gold" data-state="sold-out">
      <canvas class="edition-canvas"></canvas>
      <div class="edition-info"><div class="edition-name">Gold</div><div class="edition-meta"><span>Gilded strike / 001–25</span><span class="badge">Sold out</span></div></div>
    </div>
    <div class="edition coming" data-edition="black" data-state="coming-soon">
      <canvas class="edition-canvas"></canvas>
      <div class="edition-info"><div class="edition-name">Black</div><div class="edition-meta"><span>Obsidian strike</span><span class="badge">Autumn 2026</span></div></div>
    </div>
  </div>
</section>
</main>
<footer id="contact"><span>WastedToken Mint © 2026</span><span>For keeps, not clicks.</span></footer>

<script>
(() => {
  const hero=document.getElementById("coin-hero");
  const palette={
    bronze:["#4b1f10","#9e4e25","#e0a064","#fff0c1"],
    silver:["#353b43","#8d98a3","#dfe8eb","#ffffff"],
    gold:["#5b390b","#b98219","#f1ca68","#fff5bc"],
    black:["#08090b","#343a43","#77818b","#dbe7ed"]
  };
  function fit(canvas, scale=1){
    const r=canvas.getBoundingClientRect(), d=Math.min(2,devicePixelRatio||1);
    const w=Math.max(240,Math.floor((r.width||canvas.clientWidth||600)*d));
    const h=Math.max(240,Math.floor((r.height||canvas.clientHeight||600)*d));
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}
    return [w,h];
  }
  function ellipsePath(ctx,x,y,rx,ry){
    ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);
  }
  function raisedText(ctx,text,x,y,size,flip=false){
    ctx.save();ctx.translate(x,y);if(flip)ctx.scale(1,-1);
    ctx.textAlign="center";ctx.textBaseline="middle";ctx.font=`900 ${size}px Arial Black,Arial`;
    ctx.lineJoin="round";ctx.strokeStyle="#21160d99";ctx.lineWidth=Math.max(3,size*.13);ctx.strokeText(text,3,5);
    ctx.strokeStyle="#fff5c766";ctx.lineWidth=Math.max(1,size*.045);ctx.strokeText(text,0,0);
    ctx.fillStyle="#8b5a2b";ctx.fillText(text,0,0);ctx.restore();
  }
  function renderCoin(ctx,w,h,t,kind="bronze",mini=false){
    const p=palette[kind]||palette.bronze, cx=w/2,cy=h/2, R=Math.min(w,h)*(mini?.35:.365);
    const yaw=t*Math.PI*2, front=Math.cos(yaw)>=0, facing=Math.abs(Math.cos(yaw));
    const pitch=Math.sin(yaw)*.16;
    const sx=Math.max(.085,facing), sy=1-Math.abs(pitch)*.32;
    ctx.clearRect(0,0,w,h);
    if(!mini){
      const bg=ctx.createRadialGradient(cx*.95,cy*.75,0,cx,cy,w*.72);
      bg.addColorStop(0,"#252b30");bg.addColorStop(.6,"#12171b");bg.addColorStop(1,"#0b0d10");
      ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);
    } else {ctx.fillStyle="#d7d3c9";ctx.fillRect(0,0,w,h)}
    ctx.save();ctx.translate(cx+R*.05,cy+R*.11);ctx.scale(1,sx*.35);
    ctx.fillStyle="#00000066";ctx.filter=`blur(${R*.11}px)`;ellipsePath(ctx,0,0,R*1.02,R*.82);ctx.fill();ctx.restore();ctx.filter="none";
    ctx.save();ctx.translate(cx,cy);ctx.scale(sx,sy);
    const body=ctx.createLinearGradient(-R,-R,R,R);body.addColorStop(0,p[2]);body.addColorStop(.18,p[3]);body.addColorStop(.39,p[1]);body.addColorStop(.67,p[0]);body.addColorStop(.86,p[2]);body.addColorStop(1,p[1]);
    ctx.fillStyle=body;ellipsePath(ctx,0,0,R*1.03,R);ctx.fill();
    ctx.lineWidth=R*.065;ctx.strokeStyle=p[0];ctx.stroke();
    ctx.lineWidth=R*.018;ctx.strokeStyle=p[3]+"aa";ctx.stroke();
    ctx.save();ctx.clip();
    for(let i=-18;i<=18;i++){
      const x=i*R*.064;
      ctx.beginPath();ctx.moveTo(x,-R*1.05);ctx.lineTo(x+R*.018,R*1.05);
      ctx.lineWidth=R*.014;ctx.strokeStyle=i%2?"#150e0a66":p[3]+"77";ctx.stroke();
    }
    ctx.restore();
    if(sx>.12){
      ctx.save();ctx.scale(1,1);
      const face=ctx.createRadialGradient(-R*.28,-R*.34,R*.03,R*.08,R*.02,R*1.2);
      face.addColorStop(0,p[3]+"ee");face.addColorStop(.16,p[2]+"dd");face.addColorStop(.53,p[1]);face.addColorStop(.82,p[0]);face.addColorStop(1,p[1]);
      ctx.fillStyle=face;ellipsePath(ctx,0,0,R*.94,R*.91);ctx.fill();
      ctx.lineWidth=R*.035;ctx.strokeStyle=p[3]+"99";ctx.stroke();
      ctx.lineWidth=R*.014;ctx.strokeStyle=p[0]+"ee";ctx.stroke();
      ctx.save();ellipsePath(ctx,0,0,R*.79,R*.76);ctx.clip();
      ctx.strokeStyle=p[3]+"99";ctx.lineWidth=R*.02;ctx.beginPath();ctx.arc(-R*.03,R*.02,R*.65,0,Math.PI*2);ctx.stroke();
      ctx.strokeStyle=p[0]+"bb";ctx.lineWidth=R*.025;ctx.beginPath();ctx.arc(-R*.03,R*.02,R*.69,.25,5.95);ctx.stroke();
      const hx=Math.sin(yaw*1.7)*R*.57-R*.08;
      const shine=ctx.createLinearGradient(hx-R*.18,0,hx+R*.18,0);
      shine.addColorStop(0,"#ffffff00");shine.addColorStop(.48,"#fffbd6cc");shine.addColorStop(.52,"#ffffff");shine.addColorStop(1,"#ffffff00");
      ctx.fillStyle=shine;ctx.globalCompositeOperation="screen";ctx.fillRect(hx-R*.2,-R,R*.4,R*2);ctx.globalCompositeOperation="source-over";
      if(front){
        const mirror=Math.sin(yaw)>.2;
        ctx.save();if(mirror)ctx.scale(1,-1);
        ctx.beginPath();ctx.moveTo(0,-R*.42);ctx.lineTo(R*.3,-R*.23);ctx.lineTo(R*.27,R*.2);ctx.lineTo(0,R*.43);ctx.lineTo(-R*.27,R*.2);ctx.lineTo(-R*.3,-R*.23);ctx.closePath();
        ctx.fillStyle=p[0];ctx.fill();ctx.lineWidth=R*.025;ctx.strokeStyle=p[3];ctx.stroke();
        ctx.fillStyle=p[2];ctx.font=`900 ${R*.48}px Arial Black,Arial`;ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText("W",0,R*.01);
        ctx.strokeStyle=p[3];ctx.lineWidth=R*.014;ctx.beginPath();ctx.arc(0,0,R*.48,0,Math.PI*2);ctx.stroke();
        ctx.fillStyle=p[3];for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.beginPath();ctx.arc(Math.cos(a)*R*.62,Math.sin(a)*R*.62,R*.025,0,Math.PI*2);ctx.fill()}
        ctx.fillStyle=p[3];ctx.font=`900 ${R*.105}px Arial`;ctx.letterSpacing="2px";ctx.fillText("WASTEDTOKEN",0,R*.62);
        ctx.restore();
      }else{
        const mirror=Math.sin(yaw)<-.2;ctx.save();if(mirror)ctx.scale(1,-1);
        raisedText(ctx,"10,000",0,-R*.08,R*.28,false);
        ctx.fillStyle=p[3];ctx.textAlign="center";ctx.font=`900 ${R*.105}px Arial`;ctx.fillText("TOKENS",0,R*.27);
        ctx.font=`900 ${R*.085}px Arial`;ctx.fillText("CHALLENGE COIN",0,R*.59);ctx.restore();
      }
      ctx.restore();
    }
    ctx.restore();
    ctx.save();ctx.translate(cx,cy);ctx.scale(sx,sy);
    const glint=ctx.createRadialGradient(-R*.42,-R*.55,0,-R*.42,-R*.55,R*.65);
    glint.addColorStop(0,"#ffffffbb");glint.addColorStop(.08,"#ffffff33");glint.addColorStop(1,"#ffffff00");
    ctx.fillStyle=glint;ellipsePath(ctx,0,0,R,R);ctx.fill();ctx.restore();
  }
  let time=0, running=true;
  function draw(){const [w,h]=fit(hero);renderCoin(hero.getContext("2d"),w,h,time,"bronze");if(running)requestAnimationFrame(()=>{time=(time+.0028)%1;draw()})}
  window.demo={canvas:hero,setTime(t){time=((Number(t)%1)+1)%1;const [w,h]=fit(hero);renderCoin(hero.getContext("2d"),w,h,time,"bronze")},pause(){running=false}};
  function drawTiles(){
    document.querySelectorAll(".edition").forEach((tile,i)=>{
      const c=tile.querySelector("canvas"),[w,h]=fit(c,.8);
      renderCoin(c.getContext("2d"),w,h,[.08,.29,.47,.66][i],tile.dataset.edition,true);
    });
  }
  window.addEventListener("resize",drawTiles);
  document.querySelectorAll(".buy").forEach(b=>b.addEventListener("click",()=>{b.textContent="Added ✓";b.style.background="#ff5b2d"}));
  draw();drawTiles();
})();
</script>
</body>
</html>
